import './DataTable.css';

export type Row = {
  id: string;
  cells: string[];
};

type DataTableProps = {
  rows: Row[];
  loading: boolean;
};

const PLACEHOLDER_ROW_COUNT = 5;
const PLACEHOLDER_CELL_COUNT = 3;

export function DataTable({ rows, loading }: DataTableProps): JSX.Element {
  if (loading) {
    return (
      <table role="table" className="data-table">
        <tbody>
          {Array.from({ length: PLACEHOLDER_ROW_COUNT }, (_, rowIndex) => (
            <tr key={rowIndex}>
              {Array.from({ length: PLACEHOLDER_CELL_COUNT }, (_, cellIndex) => (
                <td key={cellIndex}>
                  <span className="data-table-shimmer" />
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    );
  }

  return (
    <table role="table" className="data-table">
      <tbody>
        {rows.map((row) => (
          <tr key={row.id}>
            {row.cells.map((cell, index) => (
              <td key={index}>{cell}</td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}
